    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=180)
    public static void nativeNestedSameDamageRevokesOnlyExtraReceipt(GameTestHelper h){
        room(h);partition(h,16);var s=friendly(h,"NativeNestedBee",7,8);var v=target(h,"NativeNestedEnemy",12,8);var a=nativeAttacker(h,"NativeNestedBee",12,9.2,true);
        var t=friendly(h,"NativeNestedGolem",7,24);var w=target(h,"NativeNestedEnemy",12,24);var b=nativeAttacker(h,"NativeNestedGolem",14,24,false);var first=watch(v,s);var second=watch(w,t);
        var probe=new NativeDebtNestedProbe(a,v,b,w);EXTRA_LISTENERS.add(probe);MinecraftForge.EVENT_BUS.register(probe);
        var seq=ready(h,s,v,a,t,w,b).thenExecute(()->{order(h,a,UnitAction.ATTACK,v,BlockPos.ZERO);order(h,b,UnitAction.ATTACK,w,BlockPos.ZERO);})
          .thenWaitUntil(()->{meleeReady(h,a,v);meleeReady(h,b,w);}).thenExecute(()->{require(h,cast(h,s,v),SkillResult.SUCCESS,"nested Bee real mark");require(h,cast(h,t,w),SkillResult.SUCCESS,"nested Golem real mark");controlledMelee(h,a,v);controlledMelee(h,b,w);h.assertTrue(probe.seen.size()==2&&probe.positive.size()==2&&v.getHealth()<1000&&w.getHealth()<1000,"both native attacks and same-source recursive HP actually ran");h.assertTrue(count(v,s)==0&&count(w,t)==0,"same DamageSource reentry forfeits native extra receipt without suppressing base HP");});
        seq.thenWaitUntil(()->{meleeReady(h,a,v);meleeReady(h,b,w);}).thenExecute(()->{controlledMelee(h,a,v);controlledMelee(h,b,w);h.assertTrue(count(v,s)==1&&count(w,t)==1,"subsequent nonrecursive installed native goals count normally");bank(h);pass("NATIVE_REENTRANT_SAME_SOURCE_REJECTED_BASE_HP_PRESERVED");}).thenSucceed();
    }
    private static final class NativeDebtNestedProbe {
        final Map<LivingEntity,Mob> lanes=new IdentityHashMap<>();final Set<LivingEntity> seen=Collections.newSetFromMap(new IdentityHashMap<>()),positive=Collections.newSetFromMap(new IdentityHashMap<>());
        NativeDebtNestedProbe(Mob a,LivingEntity v,Mob b,LivingEntity w){lanes.put(v,a);lanes.put(w,b);}
        @SubscribeEvent(priority=EventPriority.HIGHEST) public void hurt(LivingHurtEvent e){var v=e.getEntity();if(!lanes.containsKey(v)||lanes.get(v)!=e.getSource().getEntity()||!seen.add(v))return;float hp=v.getHealth();float input=v.invulnerableTime>10?((Number)rawField(v,"lastHurt")).floatValue()+10:10;v.hurt(e.getSource(),input);if(v.getHealth()<hp)positive.add(v);}
    }

