    private static final class NativeEvasionSoundProbe {
        final Mob source;final LivingEntity target;boolean seen,accepted;float healthLoss;
        NativeEvasionSoundProbe(Mob source,LivingEntity target){this.source=source;this.target=target;}
        @SubscribeEvent public void sound(net.minecraftforge.event.PlayLevelSoundEvent event){
            if(seen||event.getLevel()!=source.level()||event.getSound()==null||event.getSound().value()!=net.minecraft.sounds.SoundEvents.IRON_GOLEM_ATTACK)return;
            boolean exact=event instanceof net.minecraftforge.event.PlayLevelSoundEvent.AtEntity e&&e.getEntity()==source||event instanceof net.minecraftforge.event.PlayLevelSoundEvent.AtPosition p&&p.getPosition().distanceToSqr(source.position())<.000001;
            if(!exact)return;seen=true;target.getAttribute(AttributeRegistrar.EVASION_CHANCE.get()).setBaseValue(0);float before=target.getHealth();accepted=source.doHurtTarget(target);healthLoss=before-target.getHealth();
        }
    }

