    private static Object rawField(Object object,String name){for(Class<?> type=object.getClass();type!=null;type=type.getSuperclass())try{var f=type.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException ignored){}catch(ReflectiveOperationException error){throw new RuntimeException("raw original field "+name,error);}throw new IllegalStateException("missing raw original field "+name);}
