    private static Trace watch(LivingEntity target,FriendlyGhostUnit source){if(!listening){MinecraftForge.EVENT_BUS.register(PROBE);listening=true;}var trace=new Trace(target,source);if(PROBE.traces.put(target.getUUID(),trace)!=null)throw new IllegalStateException("duplicate exact victim observer");return trace;}
    private static void mutateDamage(LivingEntity target,java.util.function.Predicate<DamageSource> matches,Consumer<LivingDamageEvent> mutation){if(PROBE.mutations.put(target.getUUID(),new DamageMutation(matches,mutation))!=null)throw new IllegalStateException("unconsumed actual damage mutation");}
    private record DamageMutation(java.util.function.Predicate<DamageSource> matches,Consumer<LivingDamageEvent> action){}
    private static final class Trace{
        final LivingEntity target;final FriendlyGhostUnit source;final List<Hit> hits=new ArrayList<>();Hit pending;
        Trace(LivingEntity target,FriendlyGhostUnit source){this.target=target;this.source=source;}
        void finish(){if(pending!=null){pending.hpAfter=target.getHealth();pending.gelAfter=SkillEffects.shieldRemaining(target);hits.add(pending);System.out.println("FRIENDLY_DEBT_ACTUAL_RECEIPT target="+target.getUUID()+" "+pending);pending=null;}}
        Hit last(){return hits.get(hits.size()-1);}List<Hit> ordinary(){return hits.stream().filter(h->!h.settlement).toList();}List<Hit> settlements(){return hits.stream().filter(h->h.settlement).toList();}
    }
    private static final class Hit{
        final long time;final DamageSource damage;final boolean settlement;final float hpBefore;final double gelBefore;final int markAtAttack,contributorsAtAttack,nativeIframeAtAttack;float hpAfter;double gelAfter;boolean sawDamage,canceled;float eventAmount;
        Hit(Trace t,DamageSource damage){this.time=t.target.level().getGameTime();this.damage=damage;settlement=FriendlyDebtContract.isSettlement(damage);hpBefore=t.target.getHealth();gelBefore=SkillEffects.shieldRemaining(t.target);markAtAttack=mark(t.target,t.source);contributorsAtAttack=count(t.target,t.source);nativeIframeAtAttack=t.target.invulnerableTime;}
        double hpLoss(){return hpBefore-hpAfter;}double gelLoss(){return gelBefore-gelAfter;}
        @Override public String toString(){return "time="+time+" settlement="+settlement+" actor="+(damage.getEntity()==null?null:damage.getEntity().getUUID())+" direct="+(damage.getDirectEntity()==null?null:damage.getDirectEntity().getClass().getSimpleName()+"/"+damage.getDirectEntity().getUUID())+" HP="+hpBefore+"->"+hpAfter+" Gel="+gelBefore+"->"+gelAfter+" mark="+markAtAttack+" count="+contributorsAtAttack+" iframe="+nativeIframeAtAttack+" canceled="+canceled+" eventAmountDiagnosticOnly="+eventAmount;}
    }
    private static final class Probe{
        final Map<UUID,Trace> traces=new HashMap<>();final Map<UUID,List<Projectile>> projectiles=new HashMap<>();final Map<UUID,DamageMutation> mutations=new HashMap<>();
        List<Projectile> shots(Mob source){return projectiles.getOrDefault(source.getUUID(),List.of());}void finish(LivingEntity target){var t=traces.get(target.getUUID());if(t!=null)t.finish();}
        @SubscribeEvent(priority=EventPriority.LOWEST) public void join(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(e.getEntity() instanceof Projectile p&&p.getOwner() instanceof Unit u&&u.getOwnerName().startsWith(PREFIX)){projectiles.computeIfAbsent(p.getOwner().getUUID(),k->new ArrayList<>()).add(p);System.out.println("FRIENDLY_DEBT_REAL_JOIN time="+e.getLevel().getGameTime()+" source="+p.getOwner().getUUID()+" projectile="+p.getUUID()+" type="+p.getClass().getName());}}
        /** No nested-damage fixture here: next attack is the independent settlement only after ordinary returned. */
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void attack(LivingAttackEvent e){var t=traces.get(e.getEntity().getUUID());if(t!=null){t.finish();t.pending=new Hit(t,e.getSource());}}
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void damage(LivingDamageEvent e){var mutation=mutations.get(e.getEntity().getUUID());if(mutation!=null&&mutation.matches.test(e.getSource())){mutations.remove(e.getEntity().getUUID());mutation.action.accept(e);}var t=traces.get(e.getEntity().getUUID());if(t!=null&&t.pending!=null&&t.pending.damage==e.getSource()){t.pending.sawDamage=true;t.pending.canceled=e.isCanceled();t.pending.eventAmount=e.getAmount();}}
        @SubscribeEvent(priority=EventPriority.LOWEST) public void end(TickEvent.LevelTickEvent e){if(e.phase==TickEvent.Phase.END&&!e.level.isClientSide())for(var t:traces.values())if(t.target.level()==e.level)t.finish();}
    }
    private record SyncObservation(long gameTime,SkillNetwork.Sync packet){}
    private static List<SyncObservation> syncs(ServerPlayer player,FriendlyGhostUnit source){return ((RecordingHandler)player.connection).wire.syncs.stream().filter(p->p.packet().sourceUuid().equals(source.getUUID())&&p.packet().skill()==UnitSkill.FRIENDLY_DEBT_CONTRACT&&p.packet().revision()>=0).toList();}
    /** Local real PlayerList membership, not GUI/socket login simulation or direct state.sync. */
    @SuppressWarnings("unchecked") private static void syncMembership(ServerPlayer player,boolean present){try{var list=player.serverLevel().getServer().getPlayerList();var players=net.minecraft.server.players.PlayerList.class.getDeclaredField("players");var byId=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");players.setAccessible(true);byId.setAccessible(true);List<ServerPlayer> actual=(List<ServerPlayer>)players.get(list);Map<UUID,ServerPlayer> ids=(Map<UUID,ServerPlayer>)byId.get(list);if(present){if(!actual.contains(player))actual.add(player);ids.put(player.getUUID(),player);SYNC_MEMBERS.add(player);}else{actual.remove(player);ids.remove(player.getUUID(),player);SYNC_MEMBERS.remove(player);}}catch(ReflectiveOperationException error){throw new RuntimeException("real local PlayerList membership",error);}}
    private static final class RecordingHandler extends ServerGamePacketListenerImpl {
        final RecordingConnection wire;RecordingHandler(ServerPlayer p){this(p,new RecordingConnection(p.serverLevel()));}private RecordingHandler(ServerPlayer p,RecordingConnection wire){super(p.serverLevel().getServer(),wire,p);this.wire=wire;}
        @Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){wire.send(p);}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){wire.send(p,listener);}
    }
    private static final class RecordingConnection extends net.minecraft.network.Connection {
        final ServerLevel level;final List<SyncObservation> syncs=new ArrayList<>();RecordingConnection(ServerLevel level){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);this.level=level;}
        @Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){record(p);}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){record(p);}
        private void record(net.minecraft.network.protocol.Packet<?> packet){if(packet instanceof net.minecraft.network.protocol.game.ClientboundCustomPayloadPacket payload&&payload.getIdentifier().equals(DreamseekersMod.id("unit_skills"))){var bytes=new FriendlyByteBuf(payload.getData().copy());try{if(bytes.readVarInt()==1){var sync=SkillNetwork.Sync.decode(bytes);if(bytes.readableBytes()!=0)throw new IllegalStateException("trailing real Sync payload");syncs.add(new SyncObservation(level.getGameTime(),sync));}}finally{bytes.release();}}}
    }
    private static final class SilentHandler extends ServerGamePacketListenerImpl {SilentHandler(ServerPlayer p){super(p.serverLevel().getServer(),new SilentConnection(),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
    private static final class SilentConnection extends net.minecraft.network.Connection {SilentConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
